  fun getCategories(): List<SubjectMasterCategory> {
    return listOf(
      // Category 9: පරිගණක ජාල සංකල්ප සහ භූ විෂමතා
      SubjectMasterCategory(
        id = "ict_cat_9",
        categoryNumber = 9,
        titleSinhala = "පරිගණක ජාල සංකල්ප සහ ජාල භූ විෂමතා",
        icon = "🌐",
        color = Color(0xFF0284C7),
        summary = "LAN, WAN, MAN, PAN, සේවාදායක-සේවාලාභී ආකෘතිය සහ Star, Bus, Ring, Mesh ජාල විද්‍යායතන.",
        points = listOf(
          SubjectFactPoint(1, "පරිගණක ජාලයක අර්ථදැක්වීම", "දත්ත සහ සම්පත් (මුද්‍රණ යන්ත්‍ර, ආචයනය) හුවමාරු කරගැනීම සඳහා සන්නිවේදන මාධ්‍යයකින් එකිනෙක සම්බන්ධ කරන ලද පරිගණක දෙකක් හෝ වැඩි ගණනක එකතුවකි.", "ජාලකරණය මඟින් සම්පත් බෙදාහදා ගැනීම සහ සන්නිවේදනය පහසු කරයි."),
          SubjectFactPoint(2, "පෞද්ගලික ප්‍රදේශ ජාලය (PAN - Personal Area Network)", "පුද්ගලයෙකු වටා මීටර් 10 ක පමණ සීමිත පරාසයක ක්‍රියාත්මක වන කුඩාම ජාලයයි (උදා: Bluetooth, Hotspot).", "ස්මාර්ට් දුරකථනය සහ හෙඩ්සෙට් එක අතර සම්බන්ධය PAN වේ."),
          SubjectFactPoint(3, "ප්‍රාදේශීය ප්‍රදේශ ජාලය (LAN - Local Area Network)", "එක් කාමරයක්, නිවසක්, පාසලක් හෝ එක් ගොඩනැගිල්ලක් තුළ සීමා වූ පරිගණක ජාලයකි.", "ඉහළ දත්ත සම්ප්‍රේෂණ වේගයක් සහ අවම දෝෂ ප්‍රතිශතයක් පවතී."),
          SubjectFactPoint(4, "මහානගර ප්‍රදේශ ජාලය (MAN - Metropolitan Area Network)", "නගරයක් හෝ විශාල ප්‍රදේශයක් ආවරණය වන පරිදි LAN කිහිපයක් එකිනෙක සම්බන්ධ කරමින් සාදන ජාලයකි (උදා: කේබල් රූපවාහිනී ජාල).", "LAN වලට වඩා විශාල වන අතර WAN වලට වඩා කුඩාය."),
          SubjectFactPoint(5, "පුළුල් ප්‍රදේශ ජාලය (WAN - Wide Area Network)", "රටක්, මහද්වීපයක් හෝ මුළු ලෝකයම ආවරණය වන පරිදි භූගෝලීයව විසිරී ඇති ජාලයකි. හොඳම නිදසුන අන්තර්ජාලයයි (Internet).", "දුරකථන මාර්ග, චන්ද්‍රිකා සහ මුහුදුබඩ ෆයිබර් කේබල් මඟින් සම්බන්ධ වේ."),
          SubjectFactPoint(6, "සේවාදායක-සේවාලාභී ආකෘතිය (Client-Server Architecture)", "සේවාදායකය (Server) ජාල සම්පත් කළමනාකරණය කරමින් සේවා සපයන අතර, සේවාලාභීන් (Clients) එම සේවාවන් ඉල්ලා සිටියි.", "වෙබ් සර්වර්, ඊමේල් සර්වර් සහ ගොනු සර්වර් මේ යටතට වැටේ."),
          SubjectFactPoint(7, "සම සම ජාල (Peer-to-Peer - P2P Network)", "මධ්‍යම සර්වරයක් නොමැති අතර ජාලයේ සෑම පරිගණකයක්ම සමාන බලතල සහ වගකීම් සහිතව ක්‍රියා කරයි.", "සැකසීමට පහසු සහ වියදම අඩු කුඩා කාර්යාල සඳහා සුදුසුය."),
          SubjectFactPoint(8, "ජාල ස්ථලකය (Network Topology)", "ජාලයක ඇති පරිගණක සහ උපාංග එකිනෙක භෞතිකව හෝ තාර්කිකව සම්බන්ධ කර ඇති සැකැස්මයි.", "Bus, Star, Ring, Mesh සහ Tree ප්‍රධාන ස්ථලක වේ."),
          SubjectFactPoint(9, "තාරකා ස්ථලකය (Star Topology)", "සියලුම පරිගණක මධ්‍යම උපාංගයකට (Switch හෝ Hub) වෙන වෙනම කේබල් මඟින් සම්බන්ධ වේ. නූතන LAN වල බහුලවම යොදාගනී.", "එක් පරිගණකයක් බිඳවැටුණද මුළු ජාලයට බලපෑමක් නැත."),
          SubjectFactPoint(10, "බාස් ස්ථලකය (Bus Topology)", "එක් ප්‍රධාන කේබලයකට (Backbone Cable) සියලුම පරිගණක සම්බන්ධ කර ඇත. දෙකෙළවර ටර්මිනේටර් (Terminator) යොදයි.", "ප්‍රධාන කේබලය කැඩී ගියහොත් මුළු ජාලයම අඩපණ වේ."),
          SubjectFactPoint(11, "මුදු ස්ථලකය (Ring Topology)", "සෑම පරිගණකයක්ම තවත් පරිගණක දෙකකට සම්බන්ධ වී සංවෘත වළල්ලක් සාදයි. දත්ත සංඥා එක් දිශාවකට පමණක් ගමන් කරයි (Token Passing).", "එක් පරිගණකයක් හෝ කේබලයක් කැඩුණහොත් මුළු වළල්ලම බිඳවැටේ."),
          SubjectFactPoint(12, "දැල ස්ථලකය (Mesh Topology)", "ජාලයේ ඇති සෑම පරිගණකයක්ම අනෙක් සෑම පරිගණකයකටම සෘජුවම කැපවූ මාර්ගයකින් (Point-to-point) සම්බන්ධ වේ.", "ඉහළම විශ්වසනීයත්වය ඇති නමුත් කේබල් වියදම ඉතා අධිකය."),
          SubjectFactPoint(13, "දෙමුහුන් ස්ථලකය (Hybrid Topology)", "විවිධ ස්ථලක දෙකක් හෝ වැඩි ගණනක් ඒකාබද්ධ කර නිර්මාණය කරන සංකීර්ණ ජාල සැකැස්මකි (උදා: Star-Bus).", "විශාල ආයතනික ජාල සඳහා බහුලව භාවිත වේ."),
          SubjectFactPoint(14, "ජාලයක කලාප පළල (Bandwidth)", "දෙන ලද කාලයකදී සන්නිවේදන මාධ්‍යයක් හරහා සම්ප්‍රේෂණය කළ හැකි උපරිම දත්ත ප්‍රමාණයයි (bps - bits per second වලින් මනියි).", "Mbps සහ Gbps නූතන අධිවේගී මිනුම් ඒකක වේ."),
          SubjectFactPoint(15, "දත්ත සම්ප්‍රේෂණ ක්‍රම 3 (Transmission Modes)", "Simplex (එක් දිශාවකට පමණි - රූපවාහිනී), Half-Duplex (දෙපැත්තටම නමුත් වරකට එක පැත්තකට පමණි - Walkie-talkie), Full-Duplex (දෙපැත්තටම එකවර - දුරකථන).", "Full-Duplex වඩාත් කාර්යක්ෂම වේ."),
          SubjectFactPoint(16, "පැකට් ස්විචනය (Packet Switching)", "දත්ත කුඩා කොටස් වලට (Packets) කඩා ජාලය හරහා ස්වාධීන මාර්ග ඔස්සේ යවා ගමනාන්තයේදී නැවත එකලස් කිරීමේ ක්‍රමයයි.", "අන්තර්ජාලය ක්‍රියාත්මක වන මූලික ක්‍රමයයි."),
          SubjectFactPoint(17, "ජාල අතුරුමුහුණත් පත (NIC - Network Interface Card)", "පරිගණකය ජාල කේබලයට හෝ රැහැන් රහිත සංඥාවලට සම්බන්ධ කරන අභ්‍යන්තර දෘඩාංග පුවරුවයි.", "සෑම NIC පතකටම අනන්‍ය භෞතික MAC ලිපිනයක් ඇත."),
          SubjectFactPoint(18, "MAC ලිපිනය (Media Access Control Address)", "NIC පතෙහි නිෂ්පාදකයා විසින් ස්ථිරව සටහන් කරන ලද බිටු 48 කින් යුත් අනන්‍ය දෘඩාංග ලිපිනයයි (ෂඩ්දශමය අගයකි).", "උදා: 00-14-22-01-23-45."),
